using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using CurtainCall.EscapeRoute;
public static class FinishSpaceReview{
 const string Prototype="Assets/Scenes/Tests/EscapeRoute/Pursuer/EscapeRouteLabyrinthPrototype.unity";
 static void Clean(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Editor playing");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Unsaved scene");}
 public static object Close(){Clean();int n=SessionState.GetInt("RecoveryAudit.ImportWorkers",-1);if(n>=0){AssetDatabase.DesiredWorkerCount=n;SessionState.EraseInt("RecoveryAudit.ImportWorkers");}EditorApplication.Exit(0);return "Closing clean Editor for DEV sync";}
 public static object Ready(){Clean();if(SceneManager.GetActiveScene().path!=Prototype)EditorSceneManager.OpenScene(Prototype);var doll=UnityEngine.Object.FindFirstObjectByType<EscapePursuerDoll>(FindObjectsInactive.Include);if(!doll||Mathf.Abs(doll.runCycleDistance-7.48f)>.001f)throw new Exception("Refined gait not connected");if(EscapeMppmReviewConfig.TryGet(out _,out _))throw new Exception("Automated editor review still enabled");var result=new{scene=SceneManager.GetActiveScene().path,clean=!SceneManager.GetActiveScene().isDirty,run=doll.clips[(int)EscapePursuerDoll.Motion.Run].name,walk=doll.clips[(int)EscapePursuerDoll.Motion.Walk].name,distance=doll.runCycleDistance,editorPlaying=EditorApplication.isPlaying,reviewEnabled=false};File.WriteAllText(".harness/local/pursuer-space-20261116/final-editor.json",Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;}
}
